from fastapi import APIRouter, Depends, HTTPException
from ray import serve
from pydantic import BaseModel

router = APIRouter(prefix="/inference/ray-serve")

class InferencePayload(BaseModel):
    deployment_name: str
    prompt: str
    max_tokens: int = 128

@router.post("/predict")
async def predict_with_ray_deployment(
    payload: InferencePayload,
    deployment_reg: DeploymentRegistry = Depends(get_deployment_registry),
    current_user: User = Depends(get_current_user)
):
    is_allowed = await deployment_reg.is_tenant_authorized_for_deployment(
        tenant_id=current_user.tenant_id,
        deployment_name=payload.deployment_name
    )
    if not is_allowed:
        raise HTTPException(status_code=403, detail="Forbidden: Unauthorized Ray Serve deployment")

    try:
        handle = serve.get_app_handle(payload.deployment_name)
    except Exception:
        raise HTTPException(status_code=404, detail="Ray Serve deployment not found")

    result = await handle.remote(prompt=payload.prompt, max_tokens=payload.max_tokens)
    return {"deployment": payload.deployment_name, "prediction": result}
